#include <bits/stdc++.h>

using namespace std;
using ld = long double;
using ll = long long;

void solve() {
    int n, m;
    cin >> n >> m;
    vector<string> v(n);
    for (int i = 0; i < n; i++) {
        cin >> v[i];
    }
    string ans = v[0];
    for (int j = 0; j < m; j++) {
        char save = ans[j];
        for (char d = 'a'; d <= 'z'; d++) {
            ans[j] = d;
            bool flag = true;
            for (int z = 0; z < n; z++) {
                int cntErrors = 0;
                for (int c = 0; c < m; c++) {
                    if (v[z][c] != ans[c]) {
                        cntErrors++;
                    }
                }
                if (cntErrors > 1) {
                    flag = false;
                    break;
                }
            }
            if (flag) {
                cout << ans << endl;
                return;
            }
        }
        ans[j] = save;
    }
    cout << "-1" << endl;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
  int test;
  cin >> test;

  for (int tt = 0; tt < test; tt++) {
    int h, w, a, b;
    cin >> h >> w >> a >> b;

    if (h * a != w * b) {
      cout << "NO" << endl;
      continue;
    }

    vector<vector<int>> result(h, vector<int>(w, 0));

    int shift = 0;

    for (shift = 1; shift < w; shift++) {
      if (shift * h % w == 0) {
        break;
      }
    }

    for (int i = 0, dx = 0; i < h; i++, dx += shift) {
      for (int j = 0; j < a; j++) {
        result[i][(j + dx) % w] = 1;
      }
    }

    cout << "YES" << endl;

    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        cout << result[i][j];
      }

      cout << endl;
    }
  }

  return 0;
}

#include <bits/stdc++.h>

using namespace std;
using ld = long double;
using ll = long long;

void solve() {
	ll m, n;
	cin >> n >> m;
	vector<ll> v(n);
	for (int i = 0; i < n; i++) {
		string s;
		cin >> s;
		for (char c : s) {
			v[i] *= 2;
			v[i] += c - '0';
		}
	}
	ll need = ((1ll << m) - n - 1) / 2 + 1;
	ll cur = (1ll << (m - 1)) - 1;
	while (true) {
		ll left = cur + 1;
		bool flag = false;
		for (int i = 0; i < n; i++) {
			flag |= v[i] == cur;
			if (v[i] <= cur) {
				left--;
			}
		}
		if (left == need && !flag) {
			string s;
			for (int i = 0; i < m; i++) {
				s += (char)(cur % 2 + '0');
				cur /= 2;
			}
			reverse(s.begin(), s.end());
			cout << s << endl;
			return;
		} else if (left < need) {
			cur++;
		} else {
			cur--;
		}
	}
}

int main() {
	int t;
	cin >> t;
	while (t--) {
		solve();
	}
}
